<?php
require __DIR__.'/includes/db.php';
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { header('Location: ../frontend/register.html'); exit; }
$name=trim($_POST['name']??''); $roll=trim($_POST['roll_number']??''); $email=trim($_POST['email']??''); $course=trim($_POST['course']??''); $password=$_POST['password']??'';
if(strlen($name)<2 || !preg_match('/^[A-Za-z0-9\/-]{3,40}$/', $roll) || !filter_var($email,FILTER_VALIDATE_EMAIL) || $course==='' || !preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/', $password)){ exit('Invalid registration data. <a href="../frontend/register.html">Go back</a>'); }
try { $pdo->beginTransaction(); $stmt=$pdo->prepare('INSERT INTO students(name,roll_number,email,course,password_hash) VALUES(?,?,?,?,?)'); $stmt->execute([$name,$roll,$email,$course,password_hash($password,PASSWORD_DEFAULT)]); $studentId=(int)$pdo->lastInsertId();
if(!empty($_FILES['profile_file']['name'])) { $f=$_FILES['profile_file']; if($f['error']!==UPLOAD_ERR_OK || $f['size']>5*1024*1024) throw new RuntimeException('File upload failed or exceeds 5 MB.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf']; if(!isset($allowed[$mime])) throw new RuntimeException('Only JPG, PNG and PDF files are allowed.'); $stored=bin2hex(random_bytes(16)).'.'.$allowed[$mime]; $dir=__DIR__.'/uploads/profiles/'; if(!is_dir($dir)) mkdir($dir,0755,true); if(!move_uploaded_file($f['tmp_name'],$dir.$stored)) throw new RuntimeException('Could not save uploaded file.'); $pdo->prepare('INSERT INTO student_files(student_id,original_name,stored_name,file_path,mime_type,file_size,file_category) VALUES(?,?,?,?,?,?,?)')->execute([$studentId,$f['name'],$stored,'uploads/profiles/'.$stored,$mime,$f['size'],'profile']); }
$pdo->commit(); echo '<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="../frontend/style.css"><div class="form-card" style="max-width:600px;margin:10vh auto"><h2>Registration successful</h2><p>Your student profile has been created.</p><a href="view_students.php">Open student directory</a></div>';
} catch(Throwable $ex) { if($pdo->inTransaction())$pdo->rollBack(); http_response_code(400); echo 'Registration could not be completed: '.htmlspecialchars($ex->getMessage()).' <a href="../frontend/register.html">Try again</a>'; }
